  // 待機時間の上限と打ち切り。縦の棒を上限の破線で切り、打ち切りの箱を右に配置する
  const cap = p.slide("cap");
  const base = 4.2;
  const unit = 0.15;
  const capLine = base - 10 * unit;
  [1, 2, 4, 8, 16].forEach((w, i) => {
    const x = 0.8 + i * 0.85;
    const h = w * unit;
    if (base - h < capLine) {
      p.box(cap, x, base - h, 0.5, capLine - (base - h), "", { shape: "rect", fill: "accent3", tr: 70 });
      p.box(cap, x, capLine, 0.5, base - capLine, "", { shape: "rect", fill: "accent3" });
    } else {
      p.box(cap, x, base - h, 0.5, h, "", { shape: "rect", fill: "accent3" });
    }
    p.text(cap, `${String(w)} 秒`, x - 0.15, base + 0.03, 0.8, 0.3, { fontSize: 11, align: "center", color: "dk2" });
  });
  p.arrow(cap, 0.6, capLine, 4.9, capLine, { noHead: true, color: "accent6", dash: true, width: 2 });
  p.text(cap, [{ text: "上限 10 秒", bold: true, color: "accent6" }], 4.95, capLine - 0.2, 1.2, 0.4, { fontSize: 12 });
  p.box(
    cap,
    6.3,
    1.9,
    3.2,
    1.8,
    [
      { text: "5 回で打ち切り", bold: true, fontSize: 18, breakLine: true },
      { text: "呼び出し元に失敗を返す" },
    ],
    { fill: "lt2", line: "accent5", lineW: 1.5 },
  );

  // 参考にした資料。題名をリンクにし、下に内容を 1 行で書く
  const refs = p.slide("refs");
  p.badge(refs, 1, 0.5, 1.6, 0.32, { fill: "accent1" });
  p.badge(refs, 2, 0.5, 2.9, 0.32, { fill: "accent1" });
  p.text(
    refs,
    [{ text: "Marc Brooker「Exponential Backoff and Jitter」", link: "https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/" }],
    1.0,
    1.52,
    8.5,
    0.48,
    { fontSize: 16 },
  );
  p.text(refs, "AWS Architecture Blog、2015 年。ジッタの種類と、その比較", 1.0, 2.0, 8.5, 0.4, { fontSize: 12, color: "dk2" });
  p.text(
    refs,
    [{ text: "「Mastering Exponential Backoff in Distributed Systems」", link: "https://betterstack.com/community/guides/monitoring/exponential-backoff/" }],
    1.0,
    2.82,
    8.5,
    0.48,
    { fontSize: 16 },
  );
  p.text(refs, "Better Stack Community。リトライする失敗としない失敗", 1.0, 3.3, 8.5, 0.4, { fontSize: 12, color: "dk2" });

  return { theme, slides: [failures, fixed, backoff, jitter, cap, refs] };
};

export default deck;

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

